    expect(sympyStr(aseries(new Mul([fn('cos', [exp(new Mul([rational(-1), x]))]), fn('sin', [x])]), x, 6, true))).toBe('exp(-4*x)*sin(x)/24 - exp(-2*x)*sin(x)/2 + sin(x) + O(exp(-6*x), (x, oo))');
